UPDATE tasks
SET status = #{status}, stage = #{stage}, started_at = COALESCE(started_at, NOW()), updated_at = NOW()
WHERE id = #{id}

UPDATE tasks
SET status = 'SUCCESS', stage = #{stage}, result_url = #{resultUrl}, result_meta = #{resultMeta}, finished_at = NOW(), updated_at = NOW()
WHERE id = #{id}

UPDATE tasks
SET status = 'FAILED', stage = #{stage}, fail_stage = #{failStage}, fail_reason = #{failReason}, finished_at = NOW(), updated_at = NOW()
WHERE id = #{id}
